import { util } from '@aws-appsync/utils';

// Admins keep today's exact behavior (unfiltered Scan, same single-page
// cap as before this change - not fixed here, out of scope for this pass).
// Everyone else gets a real indexed lookup of what they own, newest first.
// Stashes isAdmin + primaryItems either way; later pipeline steps decide
// whether to skip their own work based on isAdmin.
export function request(ctx) {
  const groups = ctx.identity.groups ? ctx.identity.groups : [];
  const isAdmin = groups.includes('Admin');
  ctx.stash.isAdmin = isAdmin;

  if (isAdmin) {
    return { operation: 'Scan' };
  }

  return {
    operation: 'Query',
    index: 'OwnerIndex',
    query: {
      expression: '#o = :owner',
      expressionNames: { '#o': 'Owner' },
      expressionValues: util.dynamodb.toMapValues({ ':owner': ctx.identity.username }),
    },
    scanIndexForward: false,
  };
}

export function response(ctx) {
  ctx.stash.primaryItems = ctx.result.items ? ctx.result.items : [];
  return {};
}
